if(playing&&!dialog&&Math.sin(time*1.17)>0.997){let y=300+Math.sin(time*8)*150;ctx.save();ctx.globalAlpha=.13;ctx.drawImage(canvas,0,Math.floor(y*sy),canvas.width,Math.max(1,Math.floor(10*sy)),Math.sin(time*24)*8,Math.floor(y*sy),canvas.width,Math.max(1,Math.floor(10*sy)));ctx.restore()}
}
