document.querySelectorAll('.touch').forEach(button=>{const key=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);if(key==='e')interact();else keys[key]=true});['pointerup','pointercancel','lostpointercapture'].forEach(type=>button.addEventListener(type,()=>{keys[key]=false}))});
window.addEventListener('blur',()=>{keys={}});document.addEventListener('visibilitychange',()=>{if(document.hidden)keys={}});
</script></body></html>

